200:             var nodes = member.DescendantNodes().ToArray();
201:             if (nodes.Any(IsBaseDirectory) || nodes.OfType<ParameterSyntax>().Any(HasCallerFilePath))
202:             {
203:                 var step = nodes.FirstOrDefault(IsParentStep);
204:                 if (step is not null)
205:                     yield return step;
206:             }
207: 
208:             foreach (var walk in nodes.OfType<InvocationExpressionSyntax>().Where(IsRelativeWalkUp))
209:                 yield return walk;
210: 
211:             // A read of the build metadata names the attribute type and the key in the same member.
212:             if (nodes.OfType<SimpleNameSyntax>().Any(name => WithoutAttributeSuffix(name.Identifier.ValueText) == "AssemblyMetadata"))
213:             {
214:                 foreach (var literal in nodes.OfType<LiteralExpressionSyntax>().Where(literal => IsStringLiteral(literal, "McpRepositoryRoot")))
215:                     yield return literal;
216:             }
217:         }
218:     }
