224:     private static bool HasCallerFilePath(ParameterSyntax parameter) =>
225:         parameter.AttributeLists.SelectMany(list => list.Attributes)
226:             .Any(attribute => WithoutAttributeSuffix(RightmostName(attribute.Name)) == "CallerFilePath");
227: 
228:     private static bool IsParentStep(SyntaxNode node) => node switch
229:     {
230:         MemberAccessExpressionSyntax { Name.Identifier.ValueText: "Parent" } => true,
231:         MemberBindingExpressionSyntax { Name.Identifier.ValueText: "Parent" } => true,
232:         InvocationExpressionSyntax { Expression: MemberAccessExpressionSyntax { Name.Identifier.ValueText: "GetParent" } } => true,
233:         _ => false,
