236:     private static bool IsRelativeWalkUp(InvocationExpressionSyntax invocation) =>
237:         RightmostName(invocation.Expression) is "Combine" or "Join"
238:         && invocation.ArgumentList.Arguments.Any(argument => IsBaseDirectory(argument.Expression))
239:         && invocation.ArgumentList.Arguments.Any(argument =>
240:             argument.Expression is LiteralExpressionSyntax literal
241:             && literal.IsKind(SyntaxKind.StringLiteralExpression)
242:             && literal.Token.ValueText.StartsWith("..", StringComparison.Ordinal));
