244:     private static IReadOnlyList<string> AttributeKinds(AttributeSyntax attribute, IReadOnlyDictionary<string, string> aliases)
245:     {
246:         var name = WithoutAttributeSuffix(TypeName(attribute.Name, aliases));
247:         var kinds = new List<string>();
248:         if (name is "SupportedOSPlatform" or "UnsupportedOSPlatform")
249:             kinds.Add("os-attribute");
250:         if (name is "SkippableFact" or "SkippableTheory" || SetsSkipProperty(attribute))
251:             kinds.Add("skip");
