153:                 var buffer = new byte[Math.Min(MaxHistoryBytes, info.Length)];
154:                 var read = stream.Read(buffer, 0, buffer.Length);
155:                 parts.Add(System.Text.Encoding.UTF8.GetString(buffer, 0, read));
156:             }
157:             catch (IOException)
158:             {
159:                 // Skip unreadable history files.
160:             }
161:             catch (UnauthorizedAccessException)
162:             {
163:                 // Skip locked history files.
164:             }
165:         }
166:     }
167: 
168:     private static bool HistoryFileMatches(string file, string? agentSessionId, string? workspaceSlug)
169:     {
170:         if (!string.IsNullOrWhiteSpace(agentSessionId)
171:             && ContainsPathSegment(file, agentSessionId))
172:             return true;
173:         if (!string.IsNullOrWhiteSpace(workspaceSlug)
174:             && workspaceSlug.Length >= 4
175:             && ContainsPathSegment(file, workspaceSlug))
176:             return true;
177:         return false;
178:     }
179: 
180:     private static bool ContainsPathSegment(string path, string segment)
181:     {
182:         var normalized = path.Replace('\\', '/');
183:         var needle = segment.Replace('\\', '/');
184:         var index = 0;
185:         while ((index = normalized.IndexOf(needle, index, StringComparison.OrdinalIgnoreCase)) >= 0)
186:         {
187:             var beforeOk = index == 0 || IsPathSeparator(normalized[index - 1]);
188:             var afterIndex = index + needle.Length;
189:             var afterOk = afterIndex >= normalized.Length || IsPathSeparator(normalized[afterIndex]);
190:             if (beforeOk && afterOk)
191:                 return true;
192:             index = afterIndex;
193:         }
194: 
195:         return false;
196:     }
197: 
198:     private static bool IsPathSeparator(char ch) => ch is '/' or '\\' or '%' or ':' or '.';
199: 
200:     private static string ExtractTodoId(SessionLogTurnEntity turn, IReadOnlyList<string> sources)
201:     {
202:         var tagHits = turn.Tags
203:             .Select(t => t.Tag)
204:             .Where(tag => tag is not null && IsTodoId(tag))
205:             .Distinct(StringComparer.Ordinal)
206:             .ToList();
207:         if (tagHits.Count == 1)
208:             return tagHits[0]!;
209:         if (tagHits.Count > 1)
210:             return SessionLogTurnContextValidator.NoneSentinel;
211: 
212:         var counts = new Dictionary<string, int>(StringComparer.Ordinal);
213:         foreach (var source in sources)
214:         {
215:             foreach (Match match in TodoToken.Matches(source))
216:             {
217:                 var value = match.Value;
218:                 if (!IsTodoId(value) || IsEmbeddedInRequirementId(source, match.Index))
219:                     continue;
220:                 counts[value] = counts.GetValueOrDefault(value) + 1;
221:             }
222:         }
223: 
224:         if (counts.Count == 0)
225:             return SessionLogTurnContextValidator.NoneSentinel;
226:         var max = counts.Values.Max();
227:         var winners = counts.Where(pair => pair.Value == max).Select(pair => pair.Key).ToList();
228:         return winners.Count == 1 ? winners[0] : SessionLogTurnContextValidator.NoneSentinel;
229:     }
230: 
231:     private static bool IsTodoId(string value)
232:     {
233:         if (SessionLogTurnContextValidator.RequirementId.IsMatch(value))
234:             return false;
235:         return SessionLogTurnContextValidator.CanonicalTodoId.IsMatch(value)
236:             || SessionLogTurnContextValidator.IssueTodoId.IsMatch(value);
237:     }
238: 
239:     private static bool IsEmbeddedInRequirementId(string source, int index)
240:     {
241:         if (index >= 5 && source.AsSpan(index - 5, 5).Equals("TEST-", StringComparison.Ordinal))
242:             return true;
243:         if (index >= 3)
244:         {
245:             var prefix = source.AsSpan(index - 3, 3);
246:             if (prefix.Equals("TR-", StringComparison.Ordinal) || prefix.Equals("FR-", StringComparison.Ordinal))
247:                 return true;
248:         }
249: 
250:         return false;

