15: $paramsPath = Join-Path $PSScriptRoot ('hv-ug-r1-persist-' + $Mode + '-params.json')
16: function Get-ReviewTextHash {
17:     <#.SYNOPSIS Computes the SHA-256 of exact UTF-8 review text. #>
18:     [CmdletBinding()]
