25:     param([string]$Method,[object]$Parameters)
26:     $Parameters | ConvertTo-Json -Depth 100 | Set-Content -LiteralPath $paramsPath
27:     $output = & (Join-Path $PSScriptRoot 'hv-ug-r1-session.ps1') -Mode Call -Method $Method -ParamsFile $paramsPath | Out-String
28:     $documents = @(ConvertFrom-Yaml -Yaml $output -AllDocuments)
29:     if (@($documents | Where-Object { $_.type -eq 'error' -or $_.payload.result.persisted -eq $false -or $_.payload.result.queued -eq $true }).Count -gt 0) { throw ('Own session operation failed: ' + $output) }
30:     if ($output -notmatch 'type: result') { throw ('No result envelope: ' + $output) }
31:     return $output
32: }
33: switch ($Mode) {
