37:         $report = $json | ConvertFrom-Json -Depth 100
38:         if ($report.ClaimCounts.PASS -ne @($report.Claims | Where-Object Verdict -EQ PASS).Count -or $report.ClaimCounts.FAIL -ne @($report.Claims | Where-Object Verdict -EQ FAIL).Count -or $report.ClaimCounts.UNKNOWN -ne @($report.Claims | Where-Object Verdict -EQ UNKNOWN).Count) { throw 'Claim counts differ.' }
39:         if ($report.ReviewerSessionId -ne $sessionId -or $report.ReviewerRequestId -ne $requestId -or $report.ValidatorIdentity.Model -ne 'gpt-6-astra' -or $report.ValidatorIdentity.Effort -ne 'max') { throw 'Identity mismatch.' }
40:         $body = "COMPLETE VERDICT PROSE`n" + $prose + "`nCOMPLETE RECEIPT JSON`n" + $json + "`n=== VERDICT JSON ===`n" + ($report.FinalVerdictJson | ConvertTo-Json -Depth 50 -Compress)
41:         $chunkSize = 12000
