48:         [ordered]@{ TimestampLocal=(Get-Date).ToString('s'); PartCount=$total; BodyCharacters=$body.Length; BodySha256=(Get-ReviewTextHash $body); Claims=12; AllCountsAgree=$true } | ConvertTo-Json
49:     }
50:     'Append' {
