64:         }
65:         foreach ($source in $report.PrimaryWebSources) { $actions.Add([ordered]@{ order=$ordinal++; type='web_reference'; status='completed'; description='GitHub Security Advisory ' + ($source -split '/')[-1] + '; URL ' + $source + '; usage: verified patched version 10.0.13 for UG5 against the primary advisory.' }) }
66:         foreach ($path in @($mdPath,$jsonPath)) { $actions.Add([ordered]@{ order=$ordinal++; type='file_created'; status='completed'; filePath=$path; description='Complete independent review receipt, no implementation edit.' }) }
