96:     /// <summary>Scans one C# source file and returns its findings in line order, then rule order.</summary>
97:     /// <param name="relativePath">Path reported with each finding.</param>
98:     /// <param name="source">File text.</param>
99:     internal static IReadOnlyList<UnitSuitePlatformFinding> Scan(string relativePath, string source)
100:     {
101:         ArgumentNullException.ThrowIfNull(relativePath);
102:         ArgumentNullException.ThrowIfNull(source);
103:         var findings = new HashSet<(int Line, string Kind, string TestClass)>();
104:         foreach (var root in ParseBranches(source))
105:         {
106:             foreach (var (node, kind) in FindHits(root))
107:             {
108:                 var testClass = FindingOwner(node);
109:                 if (testClass is not null)
110:                     findings.Add((LineOf(node), kind, testClass));
111:             }
112:         }
113: 
114:         return findings
115:             .OrderBy(finding => finding.Line)
116:             .ThenBy(finding => Array.IndexOf(KindOrder, finding.Kind))
117:             .ThenBy(finding => finding.TestClass, StringComparer.Ordinal)
118:             .Select(finding => new UnitSuitePlatformFinding(relativePath, finding.Line, finding.Kind, finding.TestClass))
119:             .ToArray();
120:     }
121: 
122:     /// <summary>
123:     /// Parses the source once for every combination of the conditional-compilation symbols it names, so code in
124:     /// every <c>#if</c>, <c>#elif</c> and <c>#else</c> branch reachable by some combination is in a tree.
125:     /// </summary>
126:     private static IReadOnlyList<CompilationUnitSyntax> ParseBranches(string source)
127:     {
128:         var none = Parse(source, []);
129:         var symbols = new SortedSet<string>(SymbolsOf(none), StringComparer.Ordinal);
130:         var known = 0;
131:         while (symbols.Count != known && symbols.Count <= MaxConditionalSymbols)
132:         {
133:             // A directive nested in a branch that is inactive with no symbols defined names its symbols here.
134:             known = symbols.Count;
135:             symbols.UnionWith(SymbolsOf(Parse(source, symbols)).ToArray());
136:         }
137: 
138:         if (symbols.Count > MaxConditionalSymbols)
139:         {
140:             throw new InvalidOperationException(
141:                 $"The source names {symbols.Count} conditional-compilation symbols; the platform scan reads every branch and supports at most {MaxConditionalSymbols}.");
142:         }
143: 
144:         var names = symbols.ToArray();
145:         var roots = new List<CompilationUnitSyntax> { none };
146:         for (var mask = 1; mask < 1 << names.Length; mask++)
147:             roots.Add(Parse(source, names.Where((_, index) => (mask & (1 << index)) != 0)));
148: 
149:         return roots;
150:     }
151: 
152:     private static CompilationUnitSyntax Parse(string source, IEnumerable<string> symbols) =>
153:         CSharpSyntaxTree.ParseText(source, ParseOptions.WithPreprocessorSymbols(symbols)).GetCompilationUnitRoot();
154: 
155:     private static IEnumerable<string> SymbolsOf(CompilationUnitSyntax root) =>
156:         root.DescendantNodes(descendIntoTrivia: true)
157:             .OfType<ConditionalDirectiveTriviaSyntax>()
158:             .SelectMany(directive => directive.Condition.DescendantNodesAndSelf().OfType<IdentifierNameSyntax>())
159:             .Select(identifier => identifier.Identifier.ValueText);
160: 
161:     /// <summary>Every rule hit in one tree, with the node it is reported on.</summary>
162:     private static IEnumerable<(SyntaxNode Node, string Kind)> FindHits(CompilationUnitSyntax root)
163:     {
164:         var aliases = new Dictionary<string, string>(StringComparer.Ordinal);
165:         var staticTypes = new HashSet<string>(StringComparer.Ordinal);
166:         foreach (var directive in root.DescendantNodes().OfType<UsingDirectiveSyntax>())
167:         {
168:             var target = RightmostName(directive.NamespaceOrType);
169:             if (target is null)
170:                 continue;
171:             if (directive.Alias is not null)
172:                 aliases[directive.Alias.Name.Identifier.ValueText] = target;
173:             else if (directive.StaticKeyword.IsKind(SyntaxKind.StaticKeyword))
174:                 staticTypes.Add(target);
175:         }
176: 
177:         foreach (var node in root.DescendantNodes(child => child is not UsingDirectiveSyntax))
178:         {
179:             IReadOnlyList<string> kinds = node switch
180:             {
181:                 AttributeSyntax attribute => AttributeKinds(attribute, aliases),
182:                 MemberAccessExpressionSyntax access => MemberKinds(TypeName(access.Expression, aliases), access.Name.Identifier.ValueText),
183:                 IdentifierNameSyntax { Identifier.ValueText: "SkipException" } => ["skip"],
184:                 IdentifierNameSyntax identifier when IsUnqualified(identifier) => StaticImportKinds(identifier.Identifier.ValueText, staticTypes),
185:                 _ => [],
186:             };
187:             if (kinds.Count > 0 && (node is AttributeSyntax || !InNameOf(node)))
188:             {
189:                 foreach (var kind in kinds)
190:                     yield return (node, kind);
191:             }
192:         }
193:     }
