46:         new("os-check", "RuntimeInformation", static name => name == "IsOSPlatform"),
47:         new("skip", "Assert", static name => name is "Skip" or "SkipWhen" or "SkipUnless"),
48:         new("skip", "Skip", static name => name is "If" or "IfNot"),
49:         new("process-host", "SystemWorkspaceHostEnvironment", static name => name == "Instance"),
50:         new("process-host", "WorkspacePathNormalizer", static name => name == "Process"),
51:     ];
