171:             if (directive.Alias is not null)
172:                 aliases[directive.Alias.Name.Identifier.ValueText] = target;
173:             else if (directive.StaticKeyword.IsKind(SyntaxKind.StaticKeyword))
174:                 staticTypes.Add(target);
175:         }
