180:             {
181:                 AttributeSyntax attribute => AttributeKinds(attribute, aliases),
182:                 MemberAccessExpressionSyntax access => MemberKinds(TypeName(access.Expression, aliases), access.Name.Identifier.ValueText),
183:                 IdentifierNameSyntax { Identifier.ValueText: "SkipException" } => ["skip"],
184:                 IdentifierNameSyntax identifier when IsUnqualified(identifier) => StaticImportKinds(identifier.Identifier.ValueText, staticTypes),
